using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class FinalGardenQuality{
const string ScenePath="Assets/Editor/DayNightBackups/Gangstar Final Env.unity",Out="Assets/Scenes/Oasis/FinalEnvironmentRoads/GardenUtilityAtlas";
static FinalGardenQuality(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("FinalGardenQuality.request")||EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode)return;File.Delete("FinalGardenQuality.request");Run();}
static void Photo(Scene scene,Vector3 p,Vector3 target,string name)=>typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,p,target,name});
static void Run(){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath(ScenePath);if(!scene.isLoaded)throw new Exception("Saved target scene is not loaded");var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");string backup="FinalEnvironmentRoadBackup/GardenQuality-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");Directory.CreateDirectory(backup);
var mat=AssetDatabase.LoadAssetAtPath<Material>(Out+"/City Garden Utility Atlas.mat");File.Copy(AssetDatabase.GetAssetPath(mat),backup+"/Before.mat");var grass=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Scenes/Oasis/3D/Texture/Road/Grass.jpg");mat.SetTexture("_GrassDetail",grass);mat.SetFloat("_Wind",.09f);EditorUtility.SetDirty(mat);
foreach(string path in new[]{AssetDatabase.GetAssetPath(grass),Out+"/City Garden Utility Atlas.png"}){var importer=(TextureImporter)AssetImporter.GetAtPath(path);File.Copy(path+".meta",backup+"/"+Path.GetFileName(path)+".meta");importer.anisoLevel=path.EndsWith("Grass.jpg")?4:8;importer.filterMode=FilterMode.Trilinear;importer.SaveAndReimport();}
foreach(var mesh in root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.GetComponent<Renderer>()&&f.GetComponent<Renderer>().sharedMaterial==mat).Select(f=>f.sharedMesh).Distinct()){var info=mesh.uv2;var colors=mesh.colors;if(info.Length!=mesh.vertexCount||colors.Length!=mesh.vertexCount)throw new Exception("Atlas metadata missing");File.Copy(AssetDatabase.GetAssetPath(mesh),backup+"/"+Path.GetFileName(AssetDatabase.GetAssetPath(mesh)));for(int i=0;i<colors.Length;i++)colors[i].a=(Mathf.Round(info[i].x)+.5f)/16;mesh.colors=colors;EditorUtility.SetDirty(mesh);}
foreach(string name in new[]{"polySurface47","polySurface742"}){var f=root.GetComponentsInChildren<MeshFilter>(true).Single(v=>v.name==name);var mesh=f.sharedMesh;var vertices=mesh.vertices;var ids=mesh.triangles;var collider=f.GetComponent<MeshCollider>();var colliderMesh=collider?collider.sharedMesh:null;var b=f.GetComponent<Renderer>().bounds;mesh.SetUVs(3,Enumerable.Repeat(new Vector2(b.size.x,b.size.z),mesh.vertexCount).ToList());EditorUtility.SetDirty(mesh);if(!vertices.SequenceEqual(mesh.vertices)||!ids.SequenceEqual(mesh.triangles)||(collider&&collider.sharedMesh!=colliderMesh))throw new Exception("Geometry or collider changed");
log.AppendLine(name+" layout UV0 retained; paired world-scale grass/stone UVs; plot size="+b.size.x+"x"+b.size.z+"; grass repeats every 4m, paving every .87m; geometry/colliders unchanged.");}
AssetDatabase.SaveAssets();int errors=ShaderUtil.GetShaderMessages(mat.shader).Count(m=>m.severity.ToString()=="Error");if(errors>0)throw new Exception("Shader errors="+errors);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
foreach(string name in new[]{"polySurface47","polySurface742"}){var r=root.GetComponentsInChildren<MeshRenderer>(true).Single(v=>v.name==name);var p=r.bounds.center;float size=Mathf.Max(r.bounds.size.x,r.bounds.size.z);Photo(scene,p+Vector3.up*size,p,"Quality-"+name+"-Overview");Photo(scene,p+new Vector3(size*.23f,size*.18f,-size*.25f),p+Vector3.up*2,"Quality-"+name+"-Garden");Photo(scene,p+new Vector3(6,3,-12),p+new Vector3(2,0,-17),"Quality-"+name+"-Ground-Close");}
var plot=root.GetComponentsInChildren<MeshRenderer>(true).Single(v=>v.name=="polySurface47");var center=plot.bounds.center;Shader.SetGlobalFloat("_CityGardenPreviewEnabled",1);try{for(int frame=0;frame<2;frame++){Shader.SetGlobalFloat("_CityGardenPreviewTime",frame*1.25f);Photo(scene,center+new Vector3(18,9,-21),center+Vector3.up*2,"Quality-Animation-"+frame);}}finally{Shader.SetGlobalFloat("_CityGardenPreviewEnabled",0);}
var group=root.transform.Find("City Atlas Gardens and Utilities");var chunks=group.GetComponentsInChildren<MeshRenderer>(true).Where(r=>r.name.StartsWith("UtilityCovers_")&&r.enabled&&r.gameObject.activeInHierarchy).ToArray();int captured=0;foreach(int tile in new[]{0,2,3}){bool found=false;foreach(var r in chunks){var mesh=r.GetComponent<MeshFilter>().sharedMesh;var info=mesh.uv2;int i=Array.FindIndex(info,v=>Mathf.RoundToInt(v.x)==tile);if(i<0)continue;i=i/4*4;var points=mesh.vertices.Skip(i).Take(4).Select(r.transform.TransformPoint).ToArray();var p=points.Aggregate(Vector3.zero,(a,b)=>a+b)/4;Photo(scene,p+new Vector3(1.5f,2,-1.7f),p,"Quality-Utility-"+tile);captured++;found=true;break;}if(!found)log.AppendLine("No tile "+tile+" sample found");}
var texture=mat.GetTexture("_Atlas") as Texture2D;log.AppendLine("SUCCESS: two gardens upgraded, one existing atlas material and "+texture.width+"x"+texture.height+" atlas retained; no new runtime texture/material/mesh/light; utilities remain 56 combined visible batches, sample previews="+captured+"; foliage wind=.09, fountain flow unchanged; shader errors=0; backup="+backup);File.WriteAllText("FinalSunkenUnderpasses.request","finalcheck");
}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/GardenQualityReport.txt",log.ToString());}}
